select CASH_TYPE_2 from FIN_CASH_INFO
where FINPROD_ID = #{finprodId}
and FEE_ID = #{feeId}

select DISTINCT CASH_TYPE_2 from FIN_CASH_INFO
where FINPROD_ID IN (SELECT FINPROD_ID FROM FIN_PRODUCT WHERE P_FINPROD_ID = #{finprodId}) 
and FEE_ID = #{feeId}

  select nvl(sum(nvl(fee_amt,0)),0) from trd_trade_fee_detail where fee_type=#{feeType1} and trade_id in(
select deal.trade_id from trd_product_deal deal,trd_product_deal_add add1 ,fin_product prod  
where prod.finprod_type2 in('F01','F02','F03','F04','F05') and is_cancel='N'
and add1.trade_id=deal.trade_id and add1.portfolio_id=#{ptlId}  
and deal.trade_date <= to_date(#{cdate}, 'yyyy-MM-dd') and deal.finprod_id=prod.finprod_id and prod.REGIST_ORG=#{org}
)

	select nvl(sum(nvl(trade_amt,0)),0) 
	from  trd_product_deal deal,trd_product_deal_add add1 ,
		fin_product prod,TRD_TRADE_FEE_DETAIL feed
	where  
	deal.finprod_id=prod.finprod_id 
	and deal.TRADE_ID = feed.TRADE_ID
	AND deal.IS_CANCEL = #{noFlag}
