       select count(*)
        from FIN_CASH_INFO,FIN_PRODUCT,MST_FEEINFO,FIN_PRODUCT_ADD ,FIN_CASH_PAY_RULE
        where MST_FEEINFO.APPLY_TYPE in (#{relationProd}, #{relationOther})
        and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
        and FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID
        and FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
        and FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID
        and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
        and FIN_CASH_PAY_RULE.PAY_CYCLE = #{payCycle}
        and decode(MST_FEEINFO.FEE_TYPE, #{feeType_03}, 0, #{feeType_04}, 0, #{feeType_12}, 0, 1) = 1

        and FIN_CASH_INFO.FINPROD_ID = #{finprodId}



			and FIN_PRODUCT_ADD.PORTFOLIO_ID in 

				#{item}


      and MST_FEEINFO.CHARGE_TYPE = #{chargeType01}

          and MST_FEEINFO.FEE_ID = #{initValue}

         and not exists (select 1 from TRD_PRODUCT_DEAL where FIN_CASH_INFO.CASH_ID = TRD_PRODUCT_DEAL.CASH_ID
